/*************/
/* Container */
/*************/

/* Container - Variables */
.track-container {
  --clip-path: ellipse(50% 50% at 50% 50%);
  --cursor: grab;
}

/* Container - Base */
.track-container {
  filter: drop-shadow(1px 4px 3px #000);
  height: 10rem;
  position: relative;
  width: 20rem;
}
/* Container - Background */
.track-container::before {
  background: #555;
  clip-path: var(--clip-path);
  content: "";
  height: 100%;
  position: absolute;
  width: 100%;
}

/******/
/* UI */
/******/

/* Common */
/**********/

/* Common - Variables */
.track-ui {
  --angle: 60deg;
}

/* Text */
/********/

/* Text - Variables */
.track-ui__text {
  --color-fill: #fff;
  --color-glow: #f00;

  --height: 2em;
  --width: 100%;
}

/* Text - Base */
.track-ui__text {
  opacity: 0;
}

/* Text - Title */
.track-ui__text-title {
  background: var(--color-fill);
  background-clip: text;
  color: transparent;
  display: flex;
  font-size: 1.5rem;
  font-weight: 700;
  height: var(--height);
  justify-content: center;
  left: 0;
  position: absolute;
  filter: drop-shadow(0 0 5px var(--color-glow));
  width: var(--width);
}

/* Text - Title - Mapping */
.track-ui__text-title:nth-child(1) {
  top: calc(-1 * var(--height));
}
.track-ui__text-title:nth-child(2) {
  bottom: calc(-1.25 * var(--height));
}

/* Character */
/*************/

/* Character - Variables */
.track-ui__char {
  --radius: 1.5rem;
  --height: calc(2 * var(--radius));
  --width: calc(2 * var(--radius));

  --pos-x: 4;
  --pos-y: 4;
}

/* Character - Base */
.track-ui__char {
  border-radius: var(--radius);

  bottom: 50%;
  height: var(--height);
  left: calc(50% - var(--height) / 2);
  position: absolute;
  width: var(--width);
  z-index: calc(10 * var(--pos-y));
}

/* Character - Ball */
.track-ui__char-ball {
  --color-glow: #f00;
  --float: 5%;

  background: #000;
  border-radius: inherit;
  bottom: 0;
  cursor: inherit;
  height: 100%;
  left: 0;
  overflow: hidden;
  position: absolute;
  transform: translateY(var(--float));
  width: 100%;
}
.track-ui__char-ball::before {
  background: radial-gradient(
    circle at center,
    var(--color-glow),
    transparent 60%
  );
  border-radius: inherit;
  content: "";
  height: 100%;
  left: 0;
  opacity: 0;
  position: absolute;
  top: 0;
  width: 100%;
}
.track-ui__char-ball::after {
  --ratio: 15%;

  background: radial-gradient(circle at center, #fff, transparent);
  border-radius: inherit;
  box-shadow:
    0 0 0.3rem #fff,
    0 0 0.8rem rgba(255, 255, 255, 0.5),
    0 0 1rem rgba(255, 255, 255, 0.5);
  content: "";
  height: var(--ratio);
  left: 20%;
  position: absolute;
  top: 20%;
  width: var(--ratio);
}

/* Character - Shadow */
.track-ui__char-shadow {
  --float: 0.05;
  --ratio: 105%;

  background: radial-gradient(
    circle at center,
    rgba(0, 0, 0, 0.8) 25%,
    transparent
  );
  border-radius: inherit;
  bottom: calc(0% - (var(--ratio) * (1.1 + var(--float))) / 2);
  height: calc(var(--ratio) * (1.1 + var(--float)));
  left: calc(50% - (var(--ratio) * (1.1 + var(--float))) / 2);
  position: absolute;
  transform: rotateX(var(--angle));
  width: calc(var(--ratio) * (1.1 + var(--float)));
}

/* Spell */
/*********/

/* Spell - Variables */
.track-ui__spell {
  --color-border: #111;
  --color-fill: #333;
  --color-line: #fff;
  --color-glow: #90f;

  --radius: 2rem;
  --height: calc(2 * var(--radius));
  --width: calc(2 * var(--radius));
}

/* Spell - Source */
.track-ui__spell-source {
  display: none;
}

/* Spell - Magic circle */
.track-ui__spell-circle {
  --height: calc(2 * var(--radius));
  --radius: 4rem;
  --width: calc(2 * var(--radius));

  border: 2px solid var(--color-line);
  border-radius: var(--radius);
  filter: drop-shadow(0 0 0.2rem var(--color-glow));
  height: var(--height);
  left: calc(50% - var(--radius));
  opacity: 0;
  overflow: hidden;
  position: absolute;
  top: calc(50% - var(--radius));
  transform: rotateX(var(--angle));
  width: var(--width);
}
/* Spell - Magic circle - Lines */
.track-ui__spell-circle__line {
  --line-offset: 100%;
  --line-width: 0%;
  --radius: 4;
  --side: calc(1rem * sqrt(2 * pow(var(--radius), 2)));

  display: flex;
  height: var(--side);
  left: calc(50% - var(--side) / 2);
  position: absolute;
  top: calc(50% - var(--side) / 2);
  transform: rotate(calc(45deg * var(--index)));
  width: var(--side);
}
.track-ui__spell-circle__line::before,
.track-ui__spell-circle__line::after {
  content: "";
  height: 0.1rem;
}
.track-ui__spell-circle__line::before {
  width: var(--line-offset);
}
.track-ui__spell-circle__line::after {
  background: var(--color-line);
  width: var(--line-width);
}
/* Spell - Magic circle - Lines mapping */
.track-ui__spell-circle__line:nth-child(1) {
  --index: 0;
}
.track-ui__spell-circle__line:nth-child(2) {
  --index: 1;
}
.track-ui__spell-circle__line:nth-child(3) {
  --index: 2;
}
.track-ui__spell-circle__line:nth-child(4) {
  --index: 3;
}
.track-ui__spell-circle__line:nth-child(5) {
  --index: 4;
}
.track-ui__spell-circle__line:nth-child(6) {
  --index: 5;
}
.track-ui__spell-circle__line:nth-child(7) {
  --index: 6;
}
.track-ui__spell-circle__line:nth-child(8) {
  --index: 7;
}

/* Tornado */
/***********/

/* Tornado - Variables */
.track-ui__tornado {
  --color-line: #afa;
  --color-glow: #0f0;

  --wind-nb: 8;

  --radius: 1rem;
  --height: calc(2 * var(--radius));
  --width: calc(2 * var(--radius));
  --pos-x: 4;
  --pos-y: 4;
}

/* Tornado - Base */
.track-ui__tornado {
  border: none;
  border-radius: var(--radius);
  opacity: 0;
  position: absolute;
  z-index: calc(10 * var(--pos-y) + 1);
}

/* Tornado - Wind */
.track-ui__tornado-wind {
  --ratio: calc((var(--index) + 2) / var(--wind-nb));
  --height: calc(100% * var(--ratio));
  --width: calc(200% * var(--ratio));

  border-radius: var(--width);
  filter: drop-shadow(0 0 0.05rem var(--color-glow));
  height: var(--height);
  left: calc(50% - var(--width) / 2);
  position: absolute;
  top: calc(50% - var(--height) / 2);
  width: var(--width);
}
.track-ui__tornado-wind::before,
.track-ui__tornado-wind::after {
  border-radius: inherit;
  bottom: calc(25% * var(--index));
  box-shadow: inset 0 var(--offset-direction) 0 0.01rem var(--color-line);
  content: "";
  height: 100%;
  left: 0;
  position: absolute;
  width: 100%;
}
/* Tornado - Wind mapping - Direction */
.track-ui__tornado-wind::before {
  --offset-direction: 0.1rem;
}
.track-ui__tornado-wind::after {
  --offset-direction: -0.1rem;
}
/* Tornado - Wind mapping - Offset */
.track-ui__tornado-wind:nth-child(1) {
  --index: 0;
}
.track-ui__tornado-wind:nth-child(2) {
  --index: 1;
}
.track-ui__tornado-wind:nth-child(3) {
  --index: 2;
}
.track-ui__tornado-wind:nth-child(4) {
  --index: 3;
}
.track-ui__tornado-wind:nth-child(5) {
  --index: 4;
}
.track-ui__tornado-wind:nth-child(6) {
  --index: 5;
}
.track-ui__tornado-wind:nth-child(7) {
  --index: 6;
}
.track-ui__tornado-wind:nth-child(8) {
  --index: 7;
}

/****************/
/* Interactions */
/****************/

/* Text */
/*********/

/* Text */
.track-ui__text {
  transition: all 200ms linear;
}
/* Switched:checked - Show corresponding title when enabled */
.track-container:has(.track-ui__spell-source:checked):not(:hover)
  .track-ui__text.text-enabled {
  opacity: 1;
}
/* Switched:not(:checked) - Show corresponding title when disabled */
.track-container:not(:has(.track-ui__spell-source:checked))
  .track-ui__text.text-disabled {
  opacity: 1;
}

/* Character */
/*************/

/* Character */
.track-ui__char {
  pointer-events: all;
  transition: all 200ms linear;
}

/* Character - Ball */
.track-ui__char-ball {
  transition: all 200ms linear;
}
.track-ui__char-ball:active {
  cursor: grabbing;
}
.track-ui__char-ball::before {
  transition: all 500ms ease-out;
}
/* Container:hover - Makes ball float */
.track-container:has(.track-ui__spell-source:checked) .track-ui__char-ball {
  animation: ballFloat 2s infinite linear;
  opacity: 1;
}
/* Character:hover - Makes ball glow */
.track-container:has(.track-ui__spell-source:checked)
  .track-ui__char-ball:hover::before {
  opacity: 1;
}

/* Character - Shadow */
.track-ui__char-shadow {
  transition: all 200ms linear;
}
/* Container:hover - Makes ball float */
.track-container:has(.track-ui__spell-source:checked) .track-ui__char-shadow {
  animation: ballShadowFloat 2s infinite linear;
  opacity: 1;
}

/* Spell */
/*********/

/* Spell - Magic circle */
.track-ui__spell-circle {
  transition: all 0.5s ease-out;
}
/* Spell - Magic circle - Lines */
.track-ui__spell-circle__line::before {
  transition: all 0.5s linear;
}
.track-ui__spell-circle__line::after {
  transition: all 0.5s 0.25s linear;
}
/* Container:hover - Makes magic circle fade in */
.track-container:has(.track-ui__spell-source:checked):hover
  .track-ui__spell-circle {
  opacity: 1;
}
/* Container:hover - Draws magic circle's lines */
.track-container:has(.track-ui__spell-source:checked):hover
  .track-ui__spell-circle
  .track-ui__spell-circle__line {
  animation: circleDraw 0.5s forwards linear;
}

/* Tornado */
/***********/

/* Tornado - Base */
.track-ui__tornado {
  transition:
    all 0.5s linear,
    opacity 0.5s linear 1.5s;
}
/* Container:hover - Makes tornado fade in and follow cursor */
.track-container:has(.track-ui__spell-source:checked):hover .track-ui__tornado {
  --pos-x: var(--cursor-pos-x, 4);
  --pos-y: var(--cursor-pos-y, 4);

  opacity: 1;
}

/* Tornado - Wind */
.track-ui__tornado-wind::before,
.track-ui__tornado-wind::after {
  animation-delay: calc(var(--index) * 1s / var(--wind-nb));
  animation-duration: 0.5s;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
}
/* Tornado - Wind - Direction */
.track-ui__tornado-wind::before {
  animation-name: windBlowLeft;
  transition: all 0.5s linear;
}
.track-ui__tornado-wind::after {
  animation-name: windBlowRight;
}
/* Tornado - Wind - Pass behind the ball */
.track-ui__tornado-wind:nth-child(-n + 6)::before {
  opacity: min(1, pow(var(--pos-x) - 4, 2) + pow(var(--pos-y) - 4, 2));
}

/**************/
/* Animations */
/**************/

/* Character */
/*************/

/* Char - Floats ball */
@keyframes ballFloat {
  0% {
    transform: translateY(calc(-1 * var(--float)));
  }

  25% {
    transform: translateY(calc(-2 * var(--float)));
  }

  50% {
    transform: translateY(calc(-1 * var(--float)));
  }

  75% {
    transform: translateY(calc(0 * var(--float)));
  }

  100% {
    transform: translateY(calc(-1 * var(--float)));
  }
}

/* Char - Adapts ball's shadow to its floating */
@keyframes ballShadowFloat {
  0% {
    bottom: calc(0% - var(--ratio) / 2);
    height: var(--ratio);
    left: calc(50% - var(--ratio) / 2);
    width: var(--ratio);
  }

  25% {
    bottom: calc(0% - (var(--ratio) * (1 - var(--float))) / 2);
    height: calc(var(--ratio) * (1 - var(--float)));
    left: calc(50% - (var(--ratio) * (1 - var(--float))) / 2);
    width: calc(var(--ratio) * (1 - var(--float)));
  }

  50% {
    bottom: calc(0% - var(--ratio) / 2);
    height: var(--ratio);
    left: calc(50% - var(--ratio) / 2);
    width: var(--ratio);
  }

  75% {
    bottom: calc(0% - (var(--ratio) * (1 + var(--float))) / 2);
    height: calc(var(--ratio) * (1 + var(--float)));
    left: calc(50% - (var(--ratio) * (1 + var(--float))) / 2);
    width: calc(var(--ratio) * (1 + var(--float)));
  }

  100% {
    bottom: calc(0% - var(--ratio) / 2);
    height: var(--ratio);
    left: calc(50% - var(--ratio) / 2);
    width: var(--ratio);
  }
}

/* Spell */
/*********/

/* Spell - Magic circle - Draws a line */
@keyframes circleDraw {
  0% {
    --line-offset: 0%;
    --line-width: 0%;
  }

  100% {
    --line-offset: 0%;
    --line-width: 100%;
  }
}

/* Tornado */
/***********/

/* Tornado - Wind - Blows wind from right to left */
@keyframes windBlowLeft {
  0% {
    clip-path: inset(0 0 0 100%);
  }

  25% {
    clip-path: inset(0 0 0 50%);
  }

  50% {
    clip-path: inset(0 25% 0 25%);
  }

  75% {
    clip-path: inset(0 50% 0 0);
  }

  100% {
    clip-path: inset(0 100% 0 0);
  }
}

/* Tornado - Wind - Blows wind from left to right */
@keyframes windBlowRight {
  0% {
    clip-path: inset(0 100% 0 0);
  }

  25% {
    clip-path: inset(0 50% 0 0);
  }

  50% {
    clip-path: inset(0 25% 0 25%);
  }

  75% {
    clip-path: inset(0 0 0 50%);
  }

  100% {
    clip-path: inset(0 0 0 100%);
  }
}

/************/
/* Tracking */
/************/

/* Style */
/*********/

/* Grid's variable, for sizing and positionning */
.track-container {
  --grid-size-length: 9;
  --grid-size-unit: calc(100% / var(--grid-size-length));
}
/* Ensure grid and UI are properly sized and positioned */
.track-container .track-grid,
.track-container .track-ui {
  border-radius: inherit;
  cursor: var(--cursor);
  height: 100%;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
}

/* Limit grid to container */
.track-container .track-grid {
  border-radius: inherit;
  clip-path: var(--clip-path);
  display: flex;
  flex-wrap: wrap;
  overflow: hidden;
}

/* Disable pointer events for UI's container, to allow sensors hovering */
.track-container .track-ui {
  pointer-events: none;
}

/* Tracker's size and position */
.track-container .tracker {
  --tracker-height: var(--height, var(--grid-size-unit));
  --tracker-width: var(--width, var(--grid-size-unit));

  height: var(--tracker-height);
  left: calc(
    (var(--pos-x) + 0.5) * var(--grid-size-unit) - var(--tracker-width) / 2
  );
  position: absolute;
  top: calc(
    (var(--pos-y) + 0.5) * var(--grid-size-unit) - var(--tracker-height) / 2
  );
  width: var(--tracker-width);
}

/* Sensor's size and position */
.track-grid__sensor {
  height: var(--grid-size-unit);
  width: var(--grid-size-unit);
}

/* Calculations */
/****************/

.track-container .tracker {
  /* Distance to cursor, on X and Y axis */
  --vector-x: calc(var(--cursor-pos-x, var(--pos-x)) - var(--pos-x));
  --vector-y: calc(var(--cursor-pos-y, var(--pos-y)) - var(--pos-y));

  /* Maximum distance to grid's edge */
  --vector-limit: max(
    var(--pos-x),
    calc(var(--grid-size-length) - var(--pos-x)),
    var(--pos-y),
    calc(var(--grid-size-length) - var(--pos-y))
  );

  /* Maximum distance to cursor */
  --vector-max: max(
    var(--vector-x),
    calc(var(--vector-x) * -1),
    var(--vector-y),
    calc(var(--vector-y) * -1)
  );
  /* Prevent division by 0, for angle calculation */
  --vector-fix: calc(max(1, var(--vector-max)) - var(--vector-max));
  --vector-safe-max: calc(var(--vector-max) + var(--vector-fix));

  /* Distance to cursor, on X and Y axis, relative to position */
  --vector-lin-x: calc(var(--vector-x) / var(--vector-limit));
  --vector-lin-y: calc(var(--vector-y) / var(--vector-limit));
  /* Cosinus and sinus of cursor, relative to position */
  --vector-rad-cos: calc(var(--vector-x) / var(--vector-safe-max));
  --vector-rad-sin: calc(
    -1 * (var(--vector-y) - var(--vector-fix)) / var(--vector-safe-max)
  );

  /* Transformation - Rotation needed to point at cursor */
  --trans-rot-angle: atan2(var(--vector-rad-cos), var(--vector-rad-sin));
  /* Transformation - Translation in direction of cursor, within a circle */
  --trans-trc-ratio: calc(
    1 / sqrt(pow(var(--vector-rad-cos), 2) + pow(var(--vector-rad-sin), 2))
  );
  --trans-trc-x: calc(var(--vector-lin-x) * var(--trans-trc-ratio));
  --trans-trc-y: calc(var(--vector-lin-y) * var(--trans-trc-ratio));
}

/* Mapping */
/***********/

/* Cursor position, on X axis */
.track-grid__sensor:nth-of-type(9n + 1),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 1):hover) {
  --cursor-pos-x: 0;
}
.track-grid__sensor:nth-of-type(9n + 2),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 2):hover) {
  --cursor-pos-x: 1;
}
.track-grid__sensor:nth-of-type(9n + 3),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 3):hover) {
  --cursor-pos-x: 2;
}
.track-grid__sensor:nth-of-type(9n + 4),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 4):hover) {
  --cursor-pos-x: 3;
}
.track-grid__sensor:nth-of-type(9n + 5),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 5):hover) {
  --cursor-pos-x: 4;
}
.track-grid__sensor:nth-of-type(9n + 6),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 6):hover) {
  --cursor-pos-x: 5;
}
.track-grid__sensor:nth-of-type(9n + 7),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 7):hover) {
  --cursor-pos-x: 6;
}
.track-grid__sensor:nth-of-type(9n + 8),
.track-container:has(.track-grid__sensor:nth-of-type(9n + 8):hover) {
  --cursor-pos-x: 7;
}
.track-grid__sensor:nth-of-type(9n),
.track-container:has(.track-grid__sensor:nth-of-type(9n):hover) {
  --cursor-pos-x: 8;
}

/* Cursor position, on Y axis */
.track-grid__sensor:nth-of-type(n + 1):nth-of-type(-n + 9),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 1):nth-of-type(-n + 9):hover
  ) {
  --cursor-pos-y: 0;
}
.track-grid__sensor:nth-of-type(n + 10):nth-of-type(-n + 18),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 10):nth-of-type(-n + 18):hover
  ) {
  --cursor-pos-y: 1;
}
.track-grid__sensor:nth-of-type(n + 19):nth-of-type(-n + 27),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 19):nth-of-type(-n + 27):hover
  ) {
  --cursor-pos-y: 2;
}
.track-grid__sensor:nth-of-type(n + 28):nth-of-type(-n + 36),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 28):nth-of-type(-n + 36):hover
  ) {
  --cursor-pos-y: 3;
}
.track-grid__sensor:nth-of-type(n + 37):nth-of-type(-n + 45),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 37):nth-of-type(-n + 45):hover
  ) {
  --cursor-pos-y: 4;
}
.track-grid__sensor:nth-of-type(n + 46):nth-of-type(-n + 54),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 46):nth-of-type(-n + 54):hover
  ) {
  --cursor-pos-y: 5;
}
.track-grid__sensor:nth-of-type(n + 55):nth-of-type(-n + 63),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 55):nth-of-type(-n + 63):hover
  ) {
  --cursor-pos-y: 6;
}
.track-grid__sensor:nth-of-type(n + 64):nth-of-type(-n + 72),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 64):nth-of-type(-n + 72):hover
  ) {
  --cursor-pos-y: 7;
}
.track-grid__sensor:nth-of-type(n + 73):nth-of-type(-n + 81),
.track-container:has(
    .track-grid__sensor:nth-of-type(n + 73):nth-of-type(-n + 81):hover
  ) {
  --cursor-pos-y: 8;
}
